function imageDistance(f, dobj){ if(dobj===0) return Infinity; return (f*dobj)/(dobj - f); }
function magnification(f, dobj){ var di=imageDistance(f,dobj); return -di/dobj; }
function lensmaker(n, R1, R2){ if(!R1||!R2) return null; return 1/((n-1)*(1/R1 - 1/R2)); }
function classify(f, dobj){ var di=imageDistance(f,dobj); var m=magnification(f,dobj); return {di:di, m:m, real:di>0, virtual:di<0, inverted:m<0, upright:m>0}; }
var EXPORTS={ imageDistance:imageDistance, magnification:magnification, lensmaker:lensmaker, classify:classify };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.LensForgePure = EXPORTS; }
